 string QuickUnitName(string code){var names=new Dictionary<string,string>{{"usd","US Dollar"},{"eur","Euro"},{"gbp","British Pound"},{"ngn","Nigerian Naira"},{"jpy","Japanese Yen"},{"cad","Canadian Dollar"},{"aud","Australian Dollar"},{"m","Meters"},{"km","Kilometers"},{"cm","Centimeters"},{"mm","Millimeters"},{"mi","Miles"},{"ft","Feet"},{"in","Inches"},{"yd","Yards"},{"kg","Kilograms"},{"g","Grams"},{"mg","Milligrams"},{"lb","Pounds"},{"oz","Ounces"},{"c","Celsius"},{"f","Fahrenheit"}};string name;return names.TryGetValue(code,out name)?name:code.ToUpperInvariant();}
