 void RenderQuickUnitTool(){
  var card=QuickCard();var tabs=new StackPanel{Orientation=Orientation.Horizontal};foreach(string cat in new[]{"currency","length","weight","temperature"}){string selected=cat;var b=QuickButton(CultureInfo.CurrentCulture.TextInfo.ToTitleCase(cat),()=>{quickUnitCategory=selected;quickFrom=selected=="currency"?"usd":selected=="length"?"m":selected=="weight"?"kg":"c";quickTo=selected=="currency"?"eur":selected=="length"?"ft":selected=="weight"?"lb":"f";quickAmount=1;RenderQuickSearch();},7,quickUnitCategory==cat);b.Padding=new Thickness(13,6,13,6);b.BorderThickness=new Thickness(0);b.Background=quickUnitCategory==cat?QuickWash(.10):Brushes.Transparent;tabs.Children.Add(b);}card.Children.Add(new Border{Background=new SolidColorBrush(Mix(baseColor,Colors.Black,.28)),CornerRadius=new CornerRadius(10),Padding=new Thickness(3),HorizontalAlignment=HorizontalAlignment.Left,Child=tabs,Margin=new Thickness(0,0,0,20)});
